// Conversion offer logic: when paidEvents is zero, inject a discount offer into checkout
module.exports = function conversionOffer(req, res, next) {
  if (req.path === '/api/checkout' && req.method === 'POST') {
    // Add a 10% discount offer to the response
    const originalJson = res.json.bind(res);
    res.json = function(body) {
      if (body && typeof body === 'object') {
        body.offer = { discount: 10, message: 'Complete your purchase now and save 10%!' };
      }
      return originalJson(body);
    };
  }
  next();
};
